function beadPath(cx, cy, radius, hole) {
  return (
    'M' + cx + ' ' + (cy - radius) +
    'a' + radius + ' ' + radius + ' 0 1 0 0 ' + radius * 2 +
    'a' + radius + ' ' + radius + ' 0 1 0 0 ' + (-radius * 2) +
    'Z M' + cx + ' ' + (cy - hole) +
    'a' + hole + ' ' + hole + ' 0 1 0 0 ' + hole * 2 +
    'a' + hole + ' ' + hole + ' 0 1 0 0 ' + (-hole * 2) + 'Z'
  );
}

